#!/usr/bin/env bash
# AP-2 B8: P-SYM with the object and symbol maps (AP-1 section 13, B8's proof). The before arm is
# build-b8/psym-before, captured from build-b8/psym at fa727270 BEFORE any B8 edit (Release, legs/build.sh's
# flags, CCACHE_DISABLE=1). The after arm: the SAME build directory rebuilt IN PLACE at the code head
# (scripts/psym_compare.sh's precondition: one absolute build path), captured to build-b8/psym-after.
# The symbol map is generated by psym/gen_maps.py from the before arm's own objects and manifest/; the
# exceptions are psym/exceptions.txt (DECLARATION.txt P13).
# usage: psym.sh <evidence-dir>   Run as: flock /tmp/box-build.lock bash psym.sh ...
set -o pipefail
WT=/home/ghecht/Projects/hven/.claude/worktrees/agent-aad152e17d08967f4
EV=${1:?evidence dir}
P=$WT/docs/notes/data/2026-11-m8-ap2-b8/psym
if [ -n "$(pgrep -a hven_bench_cell)" ]; then echo "PGREP_BUSY"; pgrep -a hven_bench_cell; exit 3; fi
echo PGREP_EMPTY
echo "FOREGROUND_START $(date -Is)"
cd "$WT" || exit 1
mkdir -p "$EV"
export CCACHE_DISABLE=1 MKL_NUM_THREADS=1
( cd "$WT/build-b8/psym-before" && find . -type f | LC_ALL=C sort | xargs sha256sum ) | sha256sum | sed 's/^/before-capture digest /'
ninja -C "$WT/build-b8/psym" -j16 > "$EV/psym-rebuild.log" 2>&1 || { echo "REBUILD_FAIL"; tail -20 "$EV/psym-rebuild.log"; exit 1; }
tail -1 "$EV/psym-rebuild.log"
rm -rf "$WT/build-b8/psym-after"
bash scripts/psym_compare.sh capture "$WT/build-b8/psym-after" "$WT/build-b8/psym" > "$EV/capture-after.txt" 2>&1 || { echo CAPTURE_FAIL; exit 1; }
python3 "$P/gen_maps.py" "$WT/build-b8/psym-before" "$WT/build-b8/psym-after" "$EV/maps" | tee "$EV/gen-maps.txt"
PSYM_MAX_PAIRS=0 bash scripts/psym_compare.sh compare --symbol-map "$EV/maps/symbol-map.txt" \
  --exceptions "$P/exceptions.txt" "$WT/build-b8/psym-before" "$WT/build-b8/psym-after" > "$EV/compare.txt" 2>&1
rc=$?
grep -E '^(DIFFERS|P-SYM|VERDICT|SUMMARY)|STALE|COLLISION' "$EV/compare.txt" | head -40
tail -5 "$EV/compare.txt"
echo "compare rc=$rc"
echo "FOREGROUND_END $(date -Is)"
exit $rc
